input.content:
import { readFileSync } from "fs";
const html = readFileSync(new URL("./water-simulation.html", import.meta.url), "utf8");
const physicsSrc = html.slice(html.indexOf("const FLUID"), html.indexOf("const SPLAT_VS"));
const FlipFluid = new Function(physicsSrc + "\nreturn FlipFluid;")();

const fluid = new FlipFluid(3.0 * 1.77, 3.0, 64, 30000);
fluid.fillDamBreak();
const obs = { active: false, x: 0, y: 0, vx: 0, vy: 0, r: 0.3 };
const dt = 1 / 120;

const times = {};
function time(name, fn) {
  const t = performance.now();
  fn();
  times[name] = (times[name] || 0) + performance.now() - t;
}

for (let s = 0; s < 600; s++) {
  time("updateSolids", () => fluid.updateSolids(obs));
  time("integrate", () => fluid.integrateParticles(dt, -9.81));
  time("pushApart", () => fluid.pushParticlesApart(2));
  time("collisions", () => fluid.handleParticleCollisions(obs));
  time("P2G", () => fluid.transferVelocities(true, 0));
  time("density", () => fluid.updateParticleDensity());
  time("pressure", () => fluid.solveIncompressibility(30, 1.9, true));
  time("G2P", () => fluid.transferVelocities(false, 0.9));
  time("foam", () => fluid.updateFoam(dt));
}
let total = 0;
for (const [k, v] of Object.entries(times)) { console.log(k.padEnd(14), (v / 600).toFixed(3), "ms/substep"); total += v; }
console.log("TOTAL".padEnd(14), (total / 600).toFixed(3), "ms/substep ->", (total / 300).toFixed(2), "ms/frame @2 substeps");

