pushParticlesApart(numIters) {
  // count-sort particles into a hash grid
  this.numCellParticles.fill(0);
  const n = this.numParticles;
  for (let i = 0; i < n; i++) {
    const xi = clamp(Math.floor(this.pos[2*i]   * this.pInvSpacing), 0, this.pNumX - 1);
    const yi = clamp(Math.floor(this.pos[2*i+1] * this.pInvSpacing), 0, this.pNumY - 1);
    this.numCellParticles[xi * this.pNumY + yi]++;
  }
  let first = 0;
  for (let i = 0; i < this.pNumCells; i++) {
    first += this.numCellParticles[i];
    this.firstCellParticle[i] = first;
  }
  this.firstCellParticle[this.pNumCells] = first;
  for (let i = 0; i < n; i++) {
    const xi = clamp(Math.floor(this.pos[2*i]   * this.pInvSpacing), 0, this.pNumX - 1);
    const yi = clamp(Math.floor(this.pos[2*i+1] * this.pInvSpacing), 0, this.pNumY - 1);
    this.cellParticleIds[--this.firstCellParticle[xi * this.pNumY + yi]] = i;
  }

  const minDist = 2 * this.particleRadius, minDist2 = minDist * minDist;
  for (let iter = 0; iter < numIters; iter++) {
    for (let i = 0; i < n; i++) {
      const px = this.pos[2*i], py = this.pos[2*i+1];
      const pxi = clamp(Math.floor(px * this.pInvSpacing), 0, this.pNumX - 1);
      const pyi = clamp(Math.floor(py * this.pInvSpacing), 0, this.pNumY - 1);
      const x0 = Math.max(pxi - 1, 0), x1 = Math.min(pxi + 1, this.pNumX - 1);
      const y0 = Math.max(pyi - 1, 0), y1 = Math.min(pyi + 1, this.pNumY - 1);
      for (let xi = x0; xi <= x1; xi++) {
        for (let yi = y0; yi <= y1; yi++) {
          const cell = xi * this.pNumY + yi;
          const a = this.firstCellParticle[cell], b = this.firstCellParticle[cell + 1];
          for (let k = a; k < b; k++) {
            const id = this.cellParticleIds[k];
            if (id === i) continue;
            let dx = this.pos[2*id] - px, dy = this.pos[2*id+1] - py;
            const d2 = dx*dx + dy*dy;
            if (d2 > minDist2 || d2 === 0) continue;
            const d = Math.sqrt(d2), sc = 0.5 * (minDist - d) / d;
            dx *= sc; dy *= sc;
            this.pos[2*i]   -= dx; this.pos[2*i+1]  -= dy;
            this.pos[2*id]  += dx; this.pos[2*id+1] += dy;
          }
        }
      }
    }
  }
}

