function init() {
  const dpr = Math.min(window.devicePixelRatio || 1, 1.75);
  canvas.width = Math.max(2, Math.floor(canvas.clientWidth * dpr));
  canvas.height = Math.max(2, Math.floor(canvas.clientHeight * dpr));
  const aspect = clamp(canvas.width / canvas.height, 0.5, 2.2);

  const interiorW = WORLD_H * aspect;
  // capacity: a completely full tank of hex-packed particles, plus margin
  const hGuess = WORLD_H / GRID_RES, rGuess = 0.3 * hGuess;
  const maxP = Math.ceil((interiorW * WORLD_H) / (2 * rGuess * Math.sqrt(3) * rGuess)) + 2000;

  fluid = new FlipFluid(interiorW, WORLD_H, GRID_RES, maxP);
  fluid.fillDamBreak();
  renderer.allocBuffers(maxP);
  renderer.resizeField(Math.ceil(canvas.width / 2), Math.ceil(canvas.height / 2));
  document.getElementById("np").textContent = fluid.numParticles;
}

